import 'package:flutter/material.dart';import '../data/app_store.dart';import '../models/models.dart';import '../theme/operon_theme.dart';
class AiScreen extends StatefulWidget{final AppStore store;const AiScreen({super.key,required this.store});@override State<AiScreen> createState()=>_S();}
class _S extends State<AiScreen>{final q=TextEditingController();String answer='';@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('OPERON Assistant')),body:Padding(padding:const EdgeInsets.all(16),child:Column(children:[const Card(child:ListTile(leading:Icon(Icons.lock,color:OperonTheme.teal),title:Text('Private-first assistant'),subtitle:Text('Current prototype answers from recorded app data. Local RAG model comes in the AI milestone.'))),TextField(controller:q,decoration:const InputDecoration(hintText:'What should I know this shift?')),const SizedBox(height:10),FilledButton.icon(onPressed:_ask,icon:const Icon(Icons.auto_awesome),label:const Text('Ask OPERON')),const SizedBox(height:16),if(answer.isNotEmpty)Expanded(child:SingleChildScrollView(child:Card(child:Padding(padding:const EdgeInsets.all(16),child:Text(answer)))))])));}
void _ask(){final s=q.text.toLowerCase();String a;if(s.contains('maintenance')||s.contains('εκτός')){final x=widget.store.equipment.where((e)=>e.state==EquipmentState.maintenance||e.state==EquipmentState.outOfService||e.state==EquipmentState.taggedOut);a=x.isEmpty?'No matching recorded equipment state.':x.map((e)=>'${e.tag}: ${e.state.name} — ${e.note}').join('\n');}else{a='Recorded shift picture:\n• ${widget.store.tasks.where((e)=>e.state!=ActionState.completed).length} open actions\n• ${widget.store.watch.where((e)=>e.active).length} active watch items\n• ${widget.store.equipment.where((e)=>e.state==EquipmentState.maintenance).length} equipment in maintenance\n\nThis is a deterministic summary of app records, not an AI safety decision.';}setState(()=>answer=a);}}
